    const raw = await fsp.readFile(DATA_FILE, 'utf8');
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) todos = parsed.filter(isValidTodo);
  } catch (err) {
    if (err.code !== 'ENOENT') {
      console.error('[todo] could not read data file, starting empty:', err.message);
