'use strict';

const $ = (sel) => document.querySelector(sel);

const els = {
  form: $('#add-form'),
  input: $('#new-title'),
  addBtn: $('#add-btn'),
  list: $('#list'),
  summary: $('#summary'),
  clearDone: $('#clear-done'),
  filters: Array.from(document.querySelectorAll('.filter')),
  toast: $('#toast'),
};

let todos = [];
let filter = 'all';

/* --------------------------- API client --------------------------- */

async function api(method, url, body) {
  const res = await fetch(url, {
    method,
    headers: body ? { 'Content-Type': 'application/json' } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  const data = text ? JSON.parse(text) : null;
  if (!res.ok) throw new Error((data && data.error) || `Request failed (${res.status})`);
  return data;
}

/* ----------------------------- Toasts ----------------------------- */

let toastTimer;
function toast(message) {
  els.toast.textContent = message;
  els.toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => els.toast.classList.remove('show'), 2600);
}

/* ----------------------------- Render ----------------------------- */

function visibleTodos() {
  if (filter === 'active') return todos.filter((t) => !t.done);
  if (filter === 'done') return todos.filter((t) => t.done);
  return todos;
}

function render() {
  const items = visibleTodos();
  els.list.innerHTML = '';

  if (!items.length) {
    const li = document.createElement('li');
    li.className = 'empty';
    li.textContent =
      todos.length === 0 ? 'Nothing here yet — add your first task above.'
        : filter === 'active' ? 'No active tasks. Nice.'
        : 'No completed tasks yet.';
    els.list.appendChild(li);
  } else {
    for (const todo of items) els.list.appendChild(renderItem(todo));
  }

  const active = todos.filter((t) => !t.done).length;
  const done = todos.length - active;
  els.summary.textContent = todos.length
    ? `${active} active · ${done} completed`
    : 'No tasks yet';

  els.clearDone.disabled = done === 0;
  els.filters.forEach((b) => b.classList.toggle('active', b.dataset.filter === filter));
}

function renderItem(todo) {
  const li = document.createElement('li');
  li.className = 'item' + (todo.done ? ' done' : '');
  li.dataset.id = todo.id;

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.checked = todo.done;
  checkbox.setAttribute('aria-label', `Mark "${todo.title}" ${todo.done ? 'active' : 'done'}`);
  checkbox.addEventListener('change', () => toggleTodo(todo, checkbox.checked));

  const title = document.createElement('span');
  title.className = 'title';
  title.textContent = todo.title;
  title.contentEditable = 'true';
  title.spellcheck = false;
  title.title = 'Click to edit';
  title.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') { e.preventDefault(); title.blur(); }
    if (e.key === 'Escape') { title.textContent = todo.title; title.blur(); }
  });
  title.addEventListener('blur', () => {
    const next = title.textContent.replace(/\s+/g, ' ').trim();
    if (!next || next === todo.title) { title.textContent = todo.title; return; }
    renameTodo(todo, next);
  });

  const del = document.createElement('button');
  del.className = 'del';
  del.type = 'button';
  del.textContent = '×';
  del.title = 'Delete';
  del.setAttribute('aria-label', `Delete "${todo.title}"`);
  del.addEventListener('click', () => deleteTodo(todo));

  li.append(checkbox, title, del);
  return li;
}

/* ---------------------------- Actions ----------------------------- */

async function loadTodos() {
  try {
    const data = await api('GET', '/api/todos');
    todos = data.todos;
    render();
  } catch (err) {
    toast(err.message);
  }
}

async function addTodo(title) {
  try {
    const todo = await api('POST', '/api/todos', { title });
    todos.unshift(todo);
    render();
  } catch (err) {
    toast(err.message);
  }
}

